"""modlist-move: moves into a copy only, exact anchors, order/multiset guards, CRLF kept, conflict report."""

from __future__ import annotations

import json
import subprocess
import sys

from conftest import REPO

TOOL = REPO / "tools" / "modlist-move.py"

# highest priority first; a separator follows its members
LINES = [
    "# This file was automatically generated by Mod Organizer.",
    "+New Patch",
    "+New Base",
    "-Old Option",
    "+99. NEW_separator",
    "-Parked",
    "-98 TESTED & DISABLED_separator",
    "+Late Mod",
    "+02. LATE_separator",
    "+Texture Mod",
    "-Unused Alt",
    "+Base Mod",
    "+01. EARLY_separator",
]


def setup(tmp_path, lines=LINES, eol="\r\n"):
    inst = tmp_path / "inst"
    prof = inst / "profiles" / "P"
    prof.mkdir(parents=True)
    (prof / "modlist.txt").write_bytes((eol.join(lines) + eol).encode())
    mods = inst / "mods"
    for line in lines:
        if line[:1] in "+-" and not line.endswith("_separator"):
            (mods / line[1:]).mkdir(parents=True)
    return inst, prof, mods


def run(tmp_path, prof, mods, *args, out=None):
    out = out or tmp_path / "out"
    return subprocess.run([sys.executable, str(TOOL), "--mods", str(mods), "--profile", str(prof),
                           "--out", str(out), "--label", "t", *args], capture_output=True, text=True)


def result(tmp_path):
    return (tmp_path / "out" / "modlist.P.t.txt").read_bytes().decode().split("\r\n")[:-1]


def test_move_above_anchor_and_top_of_keep_plan_order(tmp_path):
    _, prof, mods = setup(tmp_path)
    plan = tmp_path / "plan.json"
    plan.write_text(json.dumps([{"mod": "New Patch", "above": "Base Mod"},
                                {"mod": "New Base", "above": "Base Mod"},
                                {"mod": "Old Option", "top_of": "02. LATE"}]))
    r = run(tmp_path, prof, mods, "--plan", str(plan))
    assert r.returncode == 0, r.stderr
    got = result(tmp_path)
    assert got.index("+New Patch") < got.index("+New Base") < got.index("+Base Mod")
    assert got.index("+New Patch") > got.index("-Unused Alt")
    assert got[got.index("-98 TESTED & DISABLED_separator") + 1] == "-Old Option"
    assert got[1] == "+99. NEW_separator"
    assert "apply with MO2 closed" in r.stdout and "modlist.txt.$(date +%Y_%m_%d_%H_%M_%S)" in r.stdout


def test_bottom_of_and_shorthand_move(tmp_path):
    _, prof, mods = setup(tmp_path)
    r = run(tmp_path, prof, mods, "--move", "New Base=>Late Mod")
    assert r.returncode == 0, r.stderr
    got = result(tmp_path)
    assert got.index("+New Base") == got.index("+Late Mod") - 1
    plan = tmp_path / "p.json"
    plan.write_text(json.dumps([{"mod": "New Patch", "bottom_of": "01. EARLY"}]))
    assert run(tmp_path, prof, mods, "--plan", str(plan)).returncode == 0
    got = result(tmp_path)
    assert got.index("+New Patch") == got.index("+01. EARLY_separator") - 1


def test_disabled_to_moves_only_disabled_mods_outside_the_separator(tmp_path):
    _, prof, mods = setup(tmp_path)
    r = run(tmp_path, prof, mods, "--disabled-to", "TESTED & DISABLED")
    assert r.returncode == 0, r.stderr
    got = result(tmp_path)
    s = got.index("-98 TESTED & DISABLED_separator")
    assert got[s - 3:s] == ["-Parked", "-Old Option", "-Unused Alt"]
    assert [l for l in got if not l.startswith("-")] == [l for l in LINES if not l.startswith("-")]


def test_ambiguous_or_missing_names_write_nothing(tmp_path):
    _, prof, mods = setup(tmp_path)
    r = run(tmp_path, prof, mods, "--move", "New Patch=>No Such Mod")
    assert r.returncode == 1 and "REFUSED" in r.stderr
    plan = tmp_path / "p.json"
    plan.write_text(json.dumps([{"mod": "New Patch", "top_of": "."}]))  # 99. / 02. / 01. separators
    r = run(tmp_path, prof, mods, "--plan", str(plan))
    assert r.returncode == 1 and "matches 3 lines" in r.stderr
    assert not (tmp_path / "out").exists()


def test_anchor_that_is_itself_moved_is_refused(tmp_path):
    _, prof, mods = setup(tmp_path)
    r = run(tmp_path, prof, mods, "--move", "New Patch=>New Base", "--move", "New Base=>Base Mod")
    assert r.returncode == 1 and "itself moved" in r.stderr


def test_refuses_to_write_inside_the_mo2_instance(tmp_path):
    inst, prof, mods = setup(tmp_path)
    for out in (prof, mods / "x", inst / "overwrite"):
        r = run(tmp_path, prof, mods, "--move", "New Base=>Base Mod", out=out)
        assert r.returncode == 2 and "inside" in r.stderr
    assert (prof / "modlist.txt").read_bytes().count(b"\r\n") == len(LINES)


def test_lf_file_stays_lf(tmp_path):
    _, prof, mods = setup(tmp_path, eol="\n")
    assert run(tmp_path, prof, mods, "--move", "New Base=>Base Mod").returncode == 0
    raw = (tmp_path / "out" / "modlist.P.t.txt").read_bytes()
    assert b"\r\n" not in raw and raw.count(b"\n") == len(LINES)


def test_conflict_report_names_files_the_move_now_loses(tmp_path):
    _, prof, mods = setup(tmp_path)
    for mod in ("New Base", "Texture Mod"):
        (mods / mod / "textures").mkdir()
        (mods / mod / "textures" / "a.dds").write_bytes(b"x")
        (mods / mod / ".DS_Store").write_bytes(b"x")
        (mods / mod / "readme.txt").write_bytes(b"x")
    r = run(tmp_path, prof, mods, "--move", "New Base=>Base Mod", "--json")
    assert r.returncode == 0, r.stderr
    found = json.loads(r.stdout)["conflicts"]
    assert found == [{"mod": "New Base", "other": "Texture Mod", "moved_mod": "loses", "files": 1,
                      "sample": ["textures/a.dds"]}]


def test_label_with_a_path_is_refused(tmp_path):
    _, prof, mods = setup(tmp_path)
    r = subprocess.run([sys.executable, str(TOOL), "--mods", str(mods), "--profile", str(prof),
                        "--out", str(tmp_path / "out"), "--label", "../../x", "--move", "New Base=>Late Mod"],
                       capture_output=True, text=True)
    assert r.returncode == 2 and "--label" in r.stderr
    assert not (tmp_path / "out").exists()


def test_output_symlink_is_not_followed(tmp_path):
    _, prof, mods = setup(tmp_path)
    live = prof / "modlist.txt"
    before = live.read_bytes()
    (tmp_path / "out").mkdir()
    (tmp_path / "out" / "modlist.P.t.txt").symlink_to(live)
    r = run(tmp_path, prof, mods, "--move", "New Base=>Late Mod")
    assert r.returncode == 2 and "refusing to write through it" in r.stderr
    assert live.read_bytes() == before


def test_apply_command_refuses_a_modlist_changed_since_the_proposal(tmp_path):
    _, prof, mods = setup(tmp_path)
    r = run(tmp_path, prof, mods, "--json", "--move", "New Base=>Late Mod")
    apply = json.loads(r.stdout)["apply"]
    assert str((tmp_path / "out").absolute()) in apply
    live = prof / "modlist.txt"
    live.write_bytes(live.read_bytes() + b"+Added By MO2\r\n")
    changed = live.read_bytes()
    a = subprocess.run(["bash", "-c", apply], capture_output=True, text=True)
    assert a.returncode != 0 and "changed since this proposal" in a.stderr
    assert live.read_bytes() == changed
    live.write_bytes(changed.replace(b"+Added By MO2\r\n", b""))
    assert subprocess.run(["bash", "-c", apply], capture_output=True).returncode == 0
    assert live.read_bytes() == (tmp_path / "out" / "modlist.P.t.txt").read_bytes()


def test_disabled_anchor_swept_by_disabled_to_is_explained(tmp_path):
    _, prof, mods = setup(tmp_path)
    r = run(tmp_path, prof, mods, "--move", "New Base=>Unused Alt", "--disabled-to", "TESTED & DISABLED")
    assert r.returncode == 1 and "is disabled, so --disabled-to" in r.stderr


def test_two_spellings_of_one_separator_keep_plan_order(tmp_path):
    _, prof, mods = setup(tmp_path)
    plan = tmp_path / "p.json"
    plan.write_text(json.dumps([{"mod": "New Patch", "top_of": "02. LATE"},
                                {"mod": "New Base", "top_of": "02. late"}]))
    r = run(tmp_path, prof, mods, "--plan", str(plan))
    assert r.returncode == 0, r.stderr
    got = result(tmp_path)
    assert got.index("+New Patch") < got.index("+New Base") < got.index("+Late Mod")


def test_an_older_apply_command_refuses_a_replaced_proposal(tmp_path):
    _, prof, mods = setup(tmp_path)
    first = json.loads(run(tmp_path, prof, mods, "--json", "--move", "New Base=>Late Mod").stdout)["apply"]
    assert run(tmp_path, prof, mods, "--move", "New Patch=>Base Mod").returncode == 0   # same label: replaced
    live = prof / "modlist.txt"
    before = live.read_bytes()
    a = subprocess.run(["bash", "-c", first], capture_output=True, text=True)
    assert a.returncode != 0 and "the proposal changed" in a.stderr
    assert live.read_bytes() == before


def test_unset_mods_folder_is_refused_not_read_as_the_cwd(tmp_path, monkeypatch):
    import runpy
    _, prof, _ = setup(tmp_path)
    monkeypatch.chdir(tmp_path)                      # "." is a directory: the bug scanned it as the mods folder
    mod = runpy.run_path(str(TOOL), run_name="modlist_move")
    monkeypatch.setitem(mod["main"].__globals__, "configured", lambda key: None)
    monkeypatch.setattr(sys, "argv", ["modlist-move", "--profile", str(prof), "--out", str(tmp_path / "out"),
                                      "--move", "New Base=>Late Mod"])
    assert mod["main"]() == 2
    assert not (tmp_path / "out").exists()


def test_a_plan_entry_that_is_not_an_object_is_a_clear_error(tmp_path):
    _, prof, mods = setup(tmp_path)
    for bad in ([None], [{"mod": "", "above": "Base Mod"}], [{"mod": "New Base", "above": 3}]):
        plan = tmp_path / "p.json"
        plan.write_text(json.dumps(bad))
        r = run(tmp_path, prof, mods, "--plan", str(plan))
        assert r.returncode != 0 and "plan entry needs a non-empty 'mod'" in r.stderr and "Traceback" not in r.stderr


def test_apply_never_overwrites_an_existing_backup(tmp_path):
    import os
    _, prof, mods = setup(tmp_path)
    apply = json.loads(run(tmp_path, prof, mods, "--json", "--move", "New Base=>Late Mod").stdout)["apply"]
    shim = tmp_path / "bin"
    shim.mkdir()
    (shim / "date").write_text("#!/bin/sh\necho 2026_01_01_00_00_00\n")
    (shim / "date").chmod(0o755)
    backup = prof / "modlist.txt.2026_01_01_00_00_00"
    backup.write_bytes(b"the original rollback copy\n")
    live = prof / "modlist.txt"
    before = live.read_bytes()
    env = dict(os.environ, PATH=f"{shim}{os.pathsep}{os.environ['PATH']}")
    a = subprocess.run(["bash", "-c", apply], capture_output=True, text=True, env=env)
    assert a.returncode != 0 and "already exists" in a.stderr
    assert backup.read_bytes() == b"the original rollback copy\n" and live.read_bytes() == before
    backup.unlink()
    assert subprocess.run(["bash", "-c", apply], capture_output=True, env=env).returncode == 0
    assert backup.read_bytes() == before
